# Let me check if there's a pattern in the transitions - like a cellular automaton rule
# Check what a non-8 cell looks like based on its 8-neighbors

from collections import Counter

def get_neighbors(r, c):
    neighs = []
    for dr in range(-1, 2):
        for dc in range(-1, 2):
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if 0 <= nr < 25 and 0 <= nc < 15:
                neighs.append(grid[nr][nc])
    return neighs

transitions = []
for r in range(25):
    for c in range(15):
        if grid[r][c] != 8:
            neighs = get_neighbors(r, c)
            transitions.append((grid[r][c], tuple(sorted(neighs))))

print("Count of non-8 values with their neighbor multisets:")
trans = Counter(transitions)
for k, v in trans.most_common(15):
    print(f"Value {k[0]} has neighbors {k[1]}: {v} times")

